__device__ __forceinline__ bool grapheme_extended_pictographic(uint32_t cp) {
  uint32_t lo = 0, hi = 156;
  while (lo < hi) {
    uint32_t mid = lo + (hi - lo) / 2;
    auto r = grapheme_extended_pictographic_ranges[mid];
    if (cp < r.first) hi = mid;
    else if (cp > r.last) lo = mid + 1;
    else return true;
  }
  return false;
}

__device__ __forceinline__ bool grapheme_extend(uint32_t cp) {
  uint32_t lo = 0, hi = 384;
  while (lo < hi) {
    uint32_t mid = lo + (hi - lo) / 2;
    auto r = grapheme_extend_ranges[mid];
    if (cp < r.first) hi = mid;
    else if (cp > r.last) lo = mid + 1;
    else return true;
  }
  return false;
}
